using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

// Train the model at startup and register the pooled prediction engine
var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
var rawData = mlContext.Data.LoadFromTextFile<ChurnRawInput>(dataPath, hasHeader: true, separatorChar: ',');

// Map "Yes"/"No" string label to boolean
var labelMappedData = mlContext.Transforms.CustomMapping<ChurnRawInput, ChurnLabelMapped>(
    (input, output) => { output.Churned = string.Equals(input.ChurnedText, "Yes", StringComparison.OrdinalIgnoreCase); },
    contractName: "ChurnLabelMapping")
    .Fit(rawData).Transform(rawData);

var split = mlContext.Data.TrainTestSplit(labelMappedData, testFraction: 0.2, seed: 42);

var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(ChurnRawInput.Region))
    .Append(mlContext.Transforms.Concatenate("Features", nameof(ChurnRawInput.Age), nameof(ChurnRawInput.Income),
        "RegionEncoded", nameof(ChurnRawInput.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Churned", featureColumnName: "Features"));

var model = pipeline.Fit(split.TrainSet);

// Evaluate and log metrics
var predictions = model.Transform(split.TestSet);
var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Churned");
Console.WriteLine($"Model metrics — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");

// Save the model and register prediction engine pool
var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");
mlContext.Model.Save(model, labelMappedData.Schema, modelPath);
builder.Services.AddPredictionEnginePool<ChurnModelInput, ChurnOutput>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapGet("/", () => "Churn Predictor API — POST /predict with { age, income, region, purchaseHistory }");

app.MapPost("/predict", (PredictionEnginePool<ChurnModelInput, ChurnOutput> pool, ChurnRequest request) =>
{
    var input = new ChurnModelInput
    {
        Age = request.Age,
        Income = request.Income,
        Region = request.Region,
        PurchaseHistory = request.PurchaseHistory
    };
    var result = pool.Predict(input);
    return Results.Ok(new { willChurn = result.PredictedLabel, probability = result.Probability });
});

app.Run();

// Raw CSV row — ChurnedText is the string column from the file
public class ChurnRawInput
{
    [LoadColumn(0)] public float Age { get; set; }
    [LoadColumn(1)] public float Income { get; set; }
    [LoadColumn(2)] public string Region { get; set; } = string.Empty;
    [LoadColumn(3)] public float PurchaseHistory { get; set; }
    [LoadColumn(4)] public string ChurnedText { get; set; } = string.Empty;
}

// Mapped label used during training
public class ChurnLabelMapped
{
    public bool Churned { get; set; }
}

// Prediction input (no label column needed)
public class ChurnModelInput
{
    public float Age { get; set; }
    public float Income { get; set; }
    public string Region { get; set; } = string.Empty;
    public float PurchaseHistory { get; set; }
}

public class ChurnOutput
{
    [ColumnName("PredictedLabel")] public bool PredictedLabel { get; set; }
    public float Probability { get; set; }
    public float Score { get; set; }
}

public record ChurnRequest(float Age, float Income, string Region, float PurchaseHistory);

